WITH deduped AS (SELECT * FROM products QUALIFY ROW_NUMBER() OVER (PARTITION BY supplier_id, category ORDER BY launch_date, id) = 1) SELECT DATE_TRUNC('MONTH', launch_date) AS activity_month, category, CORR(price, stock_qty) AS corr_price_stock_qty, ROUND(SUM(stock_qty) / NULLIF(COUNT(CASE WHEN brand = 'Initech' THEN 1 END), 0), 2) AS stock_qty_per_initech, COUNT(DISTINCT category) AS distinct_categories FROM deduped GROUP BY CUBE (DATE_TRUNC('MONTH', launch_date), category) ORDER BY stock_qty_per_initech DESC
